                        return false, string.format("element_write_failed_at_index_%d", i)
                    end
                    if #cw > 0 and not Memory.writeBatch(cw) then
                        return false, string.format("element_write_failed_at_index_%d", i)
                    end
                else
                    if not impl.set(header.arrayPtr, f, values[i]) then
                        return false, string.format("element_write_failed_at_index_%d", i)
                    end
                end
            end
        end

