    if field.container ~= "vector" then
        Memory.writeBatch({
            { address = header.containerPtr + 0x8, flags = Memory.FLAGS.INT32, value = newSize },
            { address = header.containerPtr + 0xC, flags = Memory.FLAGS.INT32, value = newSize },
