        return true
    end

    if header.arrayPtr == 0 then
        return false
    end

if field.elements then
        local Struct = loadModule("core/Struct.lua")
        local stride = field.elementStride or DEFAULT_STRIDE

        if stride > DEFAULT_STRIDE then
