__vfs['core/Struct.lua'] = [[--==================================================
-- core/Struct.lua
--==================================================
-- Reads/writes a struct element using a metadata template
-- (the `elements` sub-table on an Array field). Called by
-- core/Repeated.lua when a repeated field's slots point to struct
-- elements rather than inline scalars.
--
-- Node shapes from the metadata template:
--
-- LEAF FIELD — has `type` (string) and `offset`, no child
-- sub-tables with their own offsets:
--   { offset = 0x20, type = "Int32" }
--
-- ARRAY FIELD — has `type = "Array"`, `offset`, AND either
-- `elements` (struct-element template) or `elementType` +
-- `elementStride` (simple typed elements). Dispatched to
-- Repeated.get/set with a vector container shadow.
--
--   Array fields WITHOUT `elements` or `elementType` are skipped
--   (no reader available).
--
-- POINTER-BACKED CONTAINER — has `type` (string, not "Array"),
-- `offset`, AND child fields. Dereference base+offset, recurse.
--
-- NAMESPACE CONTAINER — no `type`, children at same base. Recurse.
--
-- Performance: Struct.get batch-reads ALL Array vector headers in
-- a single gg.getValues call before dispatching. This avoids
-- ~196 individual reads per eventRewards scan (14 rewards × 14
-- nested arrays = 196 reads at ~180ms each = 35s without batching).
-- With batching: 14 reads (one batch per reward element) = ~2s.
--
-- String indirection: caller passes `stringDirect = true` for C++
-- struct ABI (inline strings). Struct.get shadows String fields
-- with indirect=false.
--
-- Zero-value suppression: scalar fields with value 0/0.0/"" are
-- omitted. Bool values are never suppressed. Empty arrays (size=0)
-- are omitted for cleaner output. Empty containers (no readable
-- fields) are also omitted.

local Memory = loadModule("core/Memory.lua")
local Type   = loadModule("core/Type.lua")
local ZeroPage = loadModule("core/ZeroPage.lua")

local M = {}

local Logfile = loadModule("core/Logfile.lua")

local function log(...)
    if Nebula and Nebula.log then
        Logfile.log("[Struct]", ...)
    end
end

local Trace = loadModule("core/Trace.lua")

---Standardized address-trace record — see core/Trace.lua for the
---key vocabulary. pathPrefix carries the full address chain
---(e.g. "eventRewards[0]") down through nested Struct.get calls.
local function rec(tag, kv)
    Trace.rec("Struct", tag, kv)
end

---Build a dotted path for trace records ("a[0].b" style chains).
local function joinPath(prefix, key)
    if not prefix or prefix == "" then return tostring(key) end
    return tostring(prefix) .. "." .. tostring(key)
end



local typeCache = {}
local function resolveType(name)
    if typeCache[name] == nil then
        typeCache[name] = Type.resolve(name)
    end
    return typeCache[name]
end

local DEFAULT_STRIDE = 0x8

---Check if a node has child field definitions.
local function hasChildren(node)
    for _, v in pairs(node) do
        if type(v) == "table" and type(v.offset) == "number" then
            return true
        end
    end
    return false
end

---Check if a field's offset is known (not 0xBAAD).
local function isOffsetKnown(field)
    return field.offset ~= nil and field.offset ~= 0xBAAD
end

---Check if an Array field has the metadata needed to read elements.
local function isReadableArray(field)
    return field.elements ~= nil or field.elementType ~= nil
end

--- Resolve the schema used by a nested Object. `elements` references
--- a shared struct template, while legacy Object fields may still
--- carry their child fields inline.
local function nestedTemplate(field)
    if field.type == "Object" and field.elements ~= nil then
        return field.elements
    end
    return field
end

---Shadow a String field based on stringDirect ABI flag.
--   stringDirect = true  -> inline C++ std::string (indirect = false)
--   stringDirect = false -> proto2 pointer-backed (indirect = true)
--   stringDirect = nil   -> use field's declared indirect or default
local function shadowString(field, stringDirect)
    if field.type ~= "String" then
        return field
    end
    if stringDirect == true and field.indirect == nil then
        return setmetatable({ indirect = false }, { __index = field })
    end
    if stringDirect == false and field.indirect == nil then
        return setmetatable({ indirect = true }, { __index = field })
    end
    return field
end

---Build a shadow for an Array field inside a struct template.
local function shadowArray(field, stringDirect)
    local shadow = { stringDirect = stringDirect }
    return setmetatable(shadow, { __index = field })
end

---Check if a scalar value should be suppressed (0, 0.0, "").
local function isEmptyValue(field, value)
    if value == nil then return true end
    if field.type == "Bool" then return false end
    if field.type == "Enum" then return false end
    if field.type == "Int32" then return false end
    if field.type == "SafeInt32" then return false end
    if field.type == "SafeInt" then return false end
    if field.type == "JSONSafeInt" then return false end
    if type(value) == "number" then return value == 0 end
    if type(value) == "string" then return value == "" end
    return false
end

---Check if a table is empty (no key-value pairs).
local function isEmptyTable(t)
    return t == nil or next(t) == nil
end

---Pre-read batch: collect all Array field vector headers in one
---gg.getValues call. Returns a map of key → {beginPtr, endPtr, capEndPtr}.
local function batchReadArrayHeaders(base, template, stringDirect)
    local specs = {}
    local meta = {}

    for key, field in pairs(template) do
        if type(field) == "table"
           and type(field.type) == "string"
           and field.type == "Array"
           and isOffsetKnown(field)
           and isReadableArray(field) then
            local ptr = base + field.offset
            local idx = #specs
            -- An explicit container declaration wins; otherwise
            -- infer from the ABI state (inline ABI family -> vector).
            local isVector
            if field.container ~= nil then
                isVector = (field.container == "vector")
            else
                isVector = (stringDirect == true)
            end
            if isVector then
                specs[idx + 1] = { address = ptr,        flags = Memory.FLAGS.INT64 }
                specs[idx + 2] = { address = ptr + 0x8,  flags = Memory.FLAGS.INT64 }
                specs[idx + 3] = { address = ptr + 0x10, flags = Memory.FLAGS.INT64 }
                meta[#meta + 1] = { key = key, offset = idx + 1, vector = true }
            else
                specs[idx + 1] = { address = ptr,       flags = Memory.FLAGS.INT64 }
                specs[idx + 2] = { address = ptr + 0x8, flags = Memory.FLAGS.INT32 }
                specs[idx + 3] = { address = ptr + 0xC, flags = Memory.FLAGS.INT32 }
                meta[#meta + 1] = { key = key, offset = idx + 1, vector = false }
            end
        end
    end

    local result = {}
    if #specs == 0 then
        return result
    end

    local values, err = Memory.readBatch(specs)
    if not values then
        return result
    end

    for _, m in ipairs(meta) do
        if m.vector then
            local beginPtr  = values[m.offset]     and values[m.offset].value     or 0
            local endPtr    = values[m.offset + 1] and values[m.offset + 1].value or 0
            local capEndPtr = values[m.offset + 2] and values[m.offset + 2].value or 0
            -- NOTE: this pre-read path bypasses Repeated.readHeader's
            -- sanity checks (end<begin, size>capacity, bounds), so it
            -- logs the RAW header values it saw — the earliest place
            -- a corrupted vector header would surface in the trace.
            rec("readHeader", { FIELD = m.key,
                BASE = base, OFF = template[m.key].offset, ADDR = base + template[m.key].offset,
                PTR = beginPtr, BEGIN = beginPtr, END = endPtr, CAP = capEndPtr,
                INFO = "preReadHeader" })
            result[m.key] = {
                beginPtr  = beginPtr,
                endPtr    = endPtr,
                capEndPtr = capEndPtr,
            }
        else
            local arrayPtr = values[m.offset]     and values[m.offset].value     or 0
            local size     = values[m.offset + 1] and values[m.offset + 1].value or 0
            local capacity = values[m.offset + 2] and values[m.offset + 2].value or 0
            rec("readHeader", { FIELD = m.key,
                BASE = base, OFF = template[m.key].offset, ADDR = base + template[m.key].offset,
                PTR = arrayPtr, SIZE = size, CAPACITY = capacity, INFO = "preReadHeader" })
            result[m.key] = {
                containerPtr = base + template[m.key].offset,
                arrayPtr  = arrayPtr,
                size      = size,
                capacity  = capacity,
            }
        end
    end

    return result
end

---Build a Repeated-compatible header from pre-read pointers.
local function buildPreHeader(field, base, beginPtr, endPtr, capEndPtr)
    local ptr = base + field.offset
    local stride = field.elementStride or DEFAULT_STRIDE

    if beginPtr == 0 or endPtr == 0 or endPtr < beginPtr then
        return { containerPtr = ptr, arrayPtr = 0, size = 0, capacity = 0 }
    end

    local size = math.floor((endPtr - beginPtr) / stride)
    local capacity = size
    if capEndPtr ~= 0 and capEndPtr >= beginPtr then
        capacity = math.floor((capEndPtr - beginPtr) / stride)
    end

    if size < 0 then size = 0 end
    if capacity < size then capacity = size end

    rec("readHeader", { FIELD = field.name, ADDR = ptr,
        PTR = beginPtr, SIZE = size, CAPACITY = capacity, INFO = "preHeader_accepted" })
    return { containerPtr = ptr, arrayPtr = beginPtr, size = size, capacity = capacity }
end

--==================================================
-- get()
--==================================================

function M.get(base, template, stringDirect, pathPrefix)
    rec("get", { PATH = pathPrefix, BASE = base,
        INFO = "stringDirect=" .. tostring(stringDirect) })
    local result = {}

    -- Pre-pass: batch-read all readable Array vector headers in
    -- one gg.getValues call.
    local preReadHeaders = batchReadArrayHeaders(base, template, stringDirect)

    for key, field in pairs(template) do
        if type(field) == "table" then
            local container = hasChildren(field)

            if type(field.type) == "string" and field.type == "Array" then
                if isOffsetKnown(field) and isReadableArray(field) then
                    local h = preReadHeaders[key]
                    if h then
                        local preHeader
                        if h.beginPtr ~= nil then
                            if h.beginPtr ~= 0 and h.endPtr > h.beginPtr then
                                preHeader = buildPreHeader(field, base,
                                    h.beginPtr, h.endPtr, h.capEndPtr)
                            elseif h.beginPtr ~= 0 then
                                rec("null", { FIELD = key, ADDR = base + field.offset,
                                    BEGIN = h.beginPtr, END = h.endPtr,
                                    ERR = "end_le_begin_treated_empty" })
                            end
                        else
                            if h.arrayPtr ~= 0 and h.size > 0 then
                                preHeader = h
                            elseif h.arrayPtr ~= 0 then
                                rec("null", { FIELD = key, ADDR = base + field.offset,
                                    PTR = h.arrayPtr, SIZE = h.size,
                                    ERR = "size_le_zero_treated_empty" })
                            end
                        end
                        if preHeader and preHeader.size > 0 then
                            local Repeated = loadModule("core/Repeated.lua")
                            local shadow = shadowArray(field, stringDirect)
                            local arrResult = Repeated.get(base, shadow, preHeader)
                            if arrResult and not isEmptyTable(arrResult) then
                                result[key] = arrResult
                            end
                        end
                    end
                end

            elseif type(field.type) == "string" and (container or (field.type == "Object" and field.elements ~= nil)) then
                -- Pointer-backed nested Object. `elements` references a
                -- shared struct template instead of copying its fields.
                if isOffsetKnown(field) then
                    local ptr = Memory.deref(base, field.offset)
                    if ptr and ptr ~= 0 then
                        local childTemplate = nestedTemplate(field)
                        rec("nested", { PATH = pathPrefix, FIELD = key,
                            OFF = field.offset, ADDR = base + field.offset,
                            PTR = ptr, NESTED = ptr,
                            INFO = "descend:" .. tostring(field.type) })
                        -- A nested Object field may declare its OWN
                        -- stringDirect (ABI boundary, e.g. a proto2
                        -- subtree behind an inline/vector parent).
                        -- Pick it explicitly — an `and/or` chain
                        -- falls through on a false override.
                        local subDirect = stringDirect
                        if field.stringDirect ~= nil then
                            subDirect = field.stringDirect
                            rec("meta", { PATH = joinPath(pathPrefix, key), FIELD = key,
                                INFO = "abi_override stringDirect=" .. tostring(subDirect) })
                        end
                        local subResult = M.get(ptr, childTemplate, subDirect, joinPath(pathPrefix, key))
                        -- Only include non-empty containers
                        if not isEmptyTable(subResult) then
                            result[key] = subResult
                        end
                    end
                end

            elseif type(field.type) == "string" then
                -- Leaf field
                if isOffsetKnown(field) then
                    local impl = resolveType(field.type)
                    if impl then
                        local f = shadowString(field, stringDirect)
                        local value = impl.get(base, f)
                        if not isEmptyValue(field, value) then
                            result[key] = value
                            rec("get", { PATH = joinPath(pathPrefix, key), FIELD = key,
                                OFF = field.offset, ADDR = base + field.offset,
                                TYPE = tostring(field.type), VALUE = value })
                        end
                    end
                end

            elseif container then
                -- Namespace container
                local subResult = M.get(base, field, stringDirect, joinPath(pathPrefix, key))
                if not isEmptyTable(subResult) then
                    result[key] = subResult
                end
            end
        end
    end
    return result
end

--==================================================
-- set()
--==================================================

local function collectWrites(base, template, values, stringDirect, writes)
    if type(values) ~= "table" then
        return false
    end

    local allOk = true

    for key, value in pairs(values) do
        local field = template[key]
        if type(field) == "table" then
            local container = hasChildren(field)

            if type(field.type) == "string" and field.type == "Array" then
                if isOffsetKnown(field) and isReadableArray(field) then
                    local Repeated = loadModule("core/Repeated.lua")
                    local shadow = shadowArray(field, stringDirect)
                    local header, hErr = Repeated.readHeaderForSet(base, shadow)
                    if not header then
                        allOk = false
                    else
                        local ok2 = Repeated.setWithHeader(base, shadow, value, header, writes)
                        if not ok2 then
                            allOk = false
                        end
                    end
                end

            elseif type(field.type) == "string" and (container or (field.type == "Object" and field.elements ~= nil)) then
                if isOffsetKnown(field) then
                    local ptr = Memory.deref(base, field.offset)
                    local needsAlloc = not ptr or ptr == 0
                    if needsAlloc then
                        ptr = ZeroPage.allocate(0x100)
                        if ptr then
                            writes[#writes + 1] = { address = base + field.offset, flags = Memory.FLAGS.INT64, value = ptr }
                        end
                    end
                    if ptr and ptr ~= 0 then
                        -- Mirror the get-path ABI override: a nested
                        -- Object field declaring its own stringDirect
                        -- takes precedence over the walk's state.
                        local subDirect = stringDirect
                        if field.stringDirect ~= nil then
                            subDirect = field.stringDirect
                        end
                        if not collectWrites(ptr, nestedTemplate(field), value, subDirect, writes) then
                            allOk = false
                        end
                    else
                        allOk = false
                    end
                end

            elseif type(field.type) == "string" then
                if isOffsetKnown(field) then
                    local impl = resolveType(field.type)
                    if impl then
                        local f = shadowString(field, stringDirect)
                        if impl.collectWrite then
                            if not impl.collectWrite(base, f, value, writes) then
                                allOk = false
                            end
                        else
                            if not impl.set(base, f, value) then
                                allOk = false
                            end
                        end
                    end
                end

            elseif container then
                if not collectWrites(base, field, value, stringDirect, writes) then
                    allOk = false
                end
            end
        end
    end

    return allOk
end

function M.set(base, template, values, stringDirect, outWrites)
    log(string.format("[set] base=0x%X stringDirect=%s outWrites=%s", base, tostring(stringDirect), tostring(outWrites ~= nil)))
    if type(values) ~= "table" then
        return false
    end

    local writes = outWrites or {}
    local ok = collectWrites(base, template, values, stringDirect, writes)

    if not outWrites and #writes > 0 then
        local wbOk = Memory.writeBatch(writes)
        if not wbOk then
            if Nebula and Nebula.log then
                Logfile.raw("[Struct.set] writeBatch FAILED, " .. #writes .. " writes")
                for i, w in ipairs(writes) do
                    Logfile.raw(string.format("  [%d] addr=0x%X flags=%d val=%s", i, w.address, w.flags, tostring(w.value)))
                end
            end
            ok = false
        end
    end

    return ok
end

return M
]]

__vfs['core/Trace.lua'] = [[--==================================================
-- core/Trace.lua
--==================================================
-- Standardized address-trace record builder shared by EVERY
-- module that resolves or reads memory (defineApi-backed event
-- APIs, GameStatus, Memory, Repeated, Struct, Achievement, ...).
-- One logical address record per line, deterministic order,
-- easy to grep:
--
--   [PublicEvent] [resolve] MODE=cold ADDR=0x7A00000000 STRUCT=EventDefinition VER=1.73
--   [PublicEvent] [get] PATH=eventRewards[0].lootDefinition.maxCollectAmount NESTED=0x7A0000C410 OFF=0x10 ADDR=0x7A0000C420 TYPE=Int32 VALUE=50
--   [Repeated] [readHeader] FIELD=eventRewards BASE=0x7A00000000 OFF=0x100 ADDR=0x7A00000100 CONT=vector PTR=0x7A0000A000 BEGIN=0x7A0000A000 END=0x7A0000A090 CAP=0x7A0000A090 SIZE=3 CAPACITY=3 ELEM_TYPE=struct STRIDE=0x18
--   [Repeated] [elem] FIELD=eventRewards IDX=0 ELEM=0x7A0000A000 NESTED=0x7A0000A000 ELEM_TYPE=struct STRIDE=0x18
--   [Memory] [deref] BASE=0x7A00000000 OFF=0x20 ADDR=0x7A00000020 PTR=0x7A0000C410
--   [Memory] [null] PATH=... ADDR=NULL/INVALID ERR=null_pointer
--   [Memory] [cache] ID=public_event MODE=merge HIT=1 ADDR=0x7A00000000
--   [PublicEvent] [summary] OP=get ADDR=0x7A00000000 FIELDS=1 OK=1 FAIL=0 SLOWEST=startTime(0.31ms)
--
-- Tag vocabulary (required by the trace spec):
--   ADDR   — absolute address            OFF    — struct-relative offset
--   PTR    — vector/array pointer        BEGIN/END/CAP — std::vector header pointers
--   ELEM   — element address             NESTED — nested struct address
--   MODE   — cold|warm resolution        HIT    — cache hit (1/0)
--   NULL/INVALID — explicit marker, never swallow a null address
--
-- All records are gated by Nebula.log (the diagnostics switch).
-- Nebula.traceMem (raw gg.getValues/setValues I/O) and
-- Nebula.verbose (timing stats) stay separate switches.

-- Canonical key order — guarantees deterministic, greppable lines.
local Logfile = loadModule("core/Logfile.lua")

local KEY_ORDER = {
    "PATH", "FIELD", "IDX", "SEG", "OFF",
    "BASE", "ADDR", "PTR", "QWORD", "CONT", "BEGIN", "END", "CAP",
    "SIZE", "CAPACITY", "ELEM_TYPE", "STRIDE", "TYPE",
    "ELEM", "NESTED", "SLOT",
    "MODE", "HIT", "STRUCT", "VER", "OP", "ID",
    "FIELDS", "OK", "FAIL", "SLOWEST",
    "VALUE", "ERR", "INFO",
}

-- Keys that are addresses / offsets: hex form.
local HEX_KEYS = {
    BASE = true, ADDR = true, PTR = true, QWORD = true, BEGIN = true, END = true,
    CAP = true, ELEM = true, NESTED = true, SLOT = true,
    OFF = true, STRIDE = true,
}

local M = {}

---Deterministic value rendering for the VALUE= field (and unknown keys).
function M.repr(v)
    if v == nil then return "NULL/INVALID" end
    local t = type(v)
    if t == "string" then return string.format("%q", v) end
    if t == "number" then
        if math.type(v) == "integer" then
            return string.format("%d (0x%X)", v, v)
        end
        return string.format("%.6g", v)
    end
    if t == "boolean" then return tostring(v) end
    return tostring(v)
end

local function fmtVal(key, v)
    if HEX_KEYS[key] then
        if type(v) == "number" then return string.format("0x%X", v) end
        return tostring(v) -- e.g. the explicit "NULL/INVALID" marker
    end
    if key == "VALUE" then return M.repr(v) end
    return tostring(v)
end

---Emit one standardized record line. Keys absent from `kv` are
---omitted; known keys print in canonical order, unknown keys are
---appended alphabetically (still deterministic).
---@param module string @ module label, e.g. "PublicEvent", "Memory"
---@param tag string @ record tag, e.g. "get", "readHeader", "elem", "null", "summary"
---@param kv table @ key=value pairs (see KEY_ORDER for the vocabulary)
function M.rec(module, tag, kv)
    if Nebula == nil or not Nebula.log then return end
    local parts = {}
    local seen = {}
    for _, k in ipairs(KEY_ORDER) do
        local v = kv[k]
        if v ~= nil then
            seen[k] = true
            parts[#parts + 1] = k .. "=" .. fmtVal(k, v)
        end
    end
    local rest = {}
    for k in pairs(kv) do
        if not seen[k] then rest[#rest + 1] = k end
    end
    table.sort(rest)
    for _, k in ipairs(rest) do
        parts[#parts + 1] = k .. "=" .. M.repr(kv[k])
    end
    Logfile.log("[" .. tostring(module) .. "] [" .. tostring(tag) .. "] " .. table.concat(parts, " "))
end

--==================================================
-- Per-operation stats + end-of-resolution summary
--==================================================
-- beginOp() at the start of a public get()/set() (or a bulk
-- resolution), fieldDone() per field attempted, endOp() to print
-- the compact [summary]: module base, field count, OK, FAIL, and
-- the slowest fields.

---Start an operation-scoped stats session.
---@param module string
---@param op string @ e.g. "get", "set", "resolve"
---@param baseKv table|nil @ extra keys echoed into the summary (e.g. { ADDR = base })
function M.beginOp(module, op, baseKv)
    return {
        module = module,
        op = op,
        base = baseKv,
        t0 = os.clock(),
        n = 0, ok = 0, fail = 0,
        slow = {},
    }
end

---Record one attempted field (path) with success/failure. Timing
---is cumulative from beginOp — for single-field ops this is the
---field's total resolution time.
function M.fieldDone(opStats, path, ok)
    if type(opStats) ~= "table" then return end
    opStats.ms = (os.clock() - opStats.t0) * 1000
    opStats.n = opStats.n + 1
    if ok then opStats.ok = opStats.ok + 1 else opStats.fail = opStats.fail + 1 end
    opStats.slow[#opStats.slow + 1] = { path = tostring(path), ms = opStats.ms }
end

---Print the compact end-of-operation summary.
function M.endOp(opStats)
    if type(opStats) ~= "table" then return end
    if Nebula == nil or not Nebula.log then return end

    table.sort(opStats.slow, function(a, b) return a.ms > b.ms end)
    local slowStr = {}
    for i = 1, math.min(3, #opStats.slow) do
        slowStr[i] = string.format("%s(%.2fms)", opStats.slow[i].path, opStats.slow[i].ms)
    end

    local kv = {
        OP = opStats.op,
        FIELDS = opStats.n,
        OK = opStats.ok,
        FAIL = opStats.fail,
        SLOWEST = table.concat(slowStr, ","),
    }
    if opStats.base then
        for k, v in pairs(opStats.base) do kv[k] = v end
    end
    M.rec(opStats.module, "summary", kv)
end

return M
]]

__vfs['core/Type.lua'] = [[--==================================================
-- core/Type.lua
--==================================================

local M = {}

local registry = {
    Int32       = loadModule("core/types/Int32.lua"),
    SafeInt32   = loadModule("core/types/SafeInt32.lua"),
    SafeInt     = loadModule("core/types/SafeInt.lua"),
    JSONSafeInt = loadModule("core/types/SafeInt.lua"),
    Int64       = loadModule("core/types/Int64.lua"),
    Bool        = loadModule("core/types/Bool.lua"),
    Float       = loadModule("core/types/Float.lua"),
    String      = loadModule("core/types/String.lua"),
    BitMask     = loadModule("core/types/BitMask.lua"),
    Enum        = loadModule("core/types/Enum.lua"),
    Vec2        = loadModule("core/types/Vec2.lua"),
    Color3B     = loadModule("core/types/Color3B.lua"),
}

local Logfile = loadModule("core/Logfile.lua")

local function log(...)
    if Nebula and Nebula.log then
        Logfile.log("[Type]", ...)
    end
end

function M.resolve(typeName)
    local impl = registry[typeName]
    if not impl then
        log(string.format("resolve FAILED: unknown type '%s'", tostring(typeName)))
    end
    return impl
end

function M.register(typeName, implementation)
    log(string.format("register type '%s'", tostring(typeName)))
    registry[typeName] = implementation
end

return M
]]

__vfs['core/ZeroPage.lua'] = [[--==================================================
-- core/ZeroPage.lua
--==================================================

local Memory = loadModule("core/Memory.lua")
-- Bump-allocator for scratch memory, using alloc.lua's
-- safe region-selection logic.
--
-- Safety rules (from alloc.lua):
--   - Only rw-p (read/write private) regions
--   - Skip .bss, .data, [stack], [heap], thread stacks,
--     signal stacks — all look empty but are live game memory
--   - Verify zeros with gg.getValues, not gg.searchNumber
--   - Track claimed regions to prevent double-allocation
--
-- The bump allocator hands out 8-byte-aligned addresses
-- from a found zero region. When the cursor exceeds the
-- region, it re-probes for a fresh one.

local M = {}

local Logfile = loadModule("core/Logfile.lua")
local Cache   = loadModule("core/Cache.lua")

local function log(...)
    if Nebula and Nebula.log then
        Logfile.log("[ZeroPage]", ...)
    end
end



local DEFAULT_REGION_BYTES = 2048
local MIN_REGION_BYTES     = 256

local zeroPageBase   = nil
local zeroPageCursor = 0
local zeroPageSize   = 0
local _claimed       = {}

-- Reclaim bookkeeping: every handed-out block is registered, and
-- freed blocks return to a free list for reuse (zeroed on reuse).
-- free() is pure bookkeeping — no memory writes — so it is always
-- safe to call; the actual clearing happens at the next allocate.
local _registry = {}  -- addr -> { size, freed }
local _freeList = {}  -- array of { addr, size }

-- Persistence: the allocation registry lives in the PID-scoped
-- cache (core/Cache.lua), so ownership survives script reloads
-- within one game process and is auto-invalidated on a game
-- restart (the cache manifest drops everything when the PID
-- changes). The magic QWORD at the region base proves the
-- region still holds OUR data — if the game reused the memory
-- in between, we start fresh instead of handing out live bytes.
local CACHE_ID     = "zeropage"
local MAGIC        = 0x5A45524F50414745  -- "ZEROPAGE"
local _restoreTried = false

local function persistSnapshot()
    if zeroPageBase == nil then return end
    pcall(Cache.save, CACHE_ID, {
        base     = zeroPageBase,
        size     = zeroPageSize,
        cursor   = zeroPageCursor,
        registry = _registry,
        freeList = _freeList,
        claimed  = _claimed,
    })
end

-- Rebuild ZeroPage state from the PID-scoped cache after a script
-- reload. Called lazily from allocate() only.
local function restoreFromCache()
    if zeroPageBase ~= nil or _restoreTried then return false end
    _restoreTried = true
    local ok, cached = pcall(Cache.load, CACHE_ID)
    if not ok or type(cached) ~= "table" then return false end
    local base, size, cursor = cached.base, cached.size, cached.cursor
    if type(base) ~= "number" or type(size) ~= "number" or type(cursor) ~= "number" then
        return false
    end
    if Memory.read(base, Memory.FLAGS.INT64) ~= MAGIC then
        log("restore: region magic mismatch — starting fresh")
        return false
    end
    zeroPageBase   = base
    zeroPageSize   = size
    zeroPageCursor = math.max(cursor, 8)
    if type(cached.claimed) == "table" then
        for k, info in pairs(cached.claimed) do
            if type(k) == "number" and type(info) == "table" then
                _claimed[k] = { size = info.size }
            end
        end
    end
    if type(cached.registry) == "table" then
        for addr, e in pairs(cached.registry) do
            if type(addr) == "number" and type(e) == "table" then
                _registry[addr] = { size = e.size, freed = e.freed == true }
            end
        end
    end
    if type(cached.freeList) == "table" then
        for _, b in ipairs(cached.freeList) do
            if type(b) == "table" and type(b.addr) == "number" and type(b.size) == "number" then
                _freeList[#_freeList + 1] = { addr = b.addr, size = b.size }
            end
        end
    end
    log(string.format("restore: region=0x%X cursor=%d/%d (PID-scoped cache hit)",
        base, zeroPageCursor, size))
    return true
end

-- Returns true for regions that are unsafe to write into.
-- Only rw-p (read/write private) pages are safe.
local function isDangerousRegion(region)
    local perms = region.type or ""
    if perms ~= "" and perms ~= "rw-p" then
        return true
    end
    local name         = region.name         or ""
    local internalName = region.internalName or ""
    if name:match("%.bss") or internalName:match(":bss") then
        return true
    end
    if name:match("%.data") or internalName:match(":data") then
        return true
    end
    if name:match("%[stack%]")
        or name:match("stack_and_tls")
        or name:match("signal stack")
        or internalName:match("stack_and_tls")
        or internalName:match("signal stack")
        or name:match("%[heap%]") then
        return true
    end
    return false
end

local function isClaimed(base, size)
    for claimedBase, info in pairs(_claimed) do
        local claimedEnd = claimedBase + info.size
        local reqEnd     = base + size
        if base < claimedEnd and reqEnd > claimedBase then
            return true
        end
    end
    return false
end

-- Verify that a range of memory is all zeros using gg.getValues.
-- Reads in chunks to avoid GG batch limits.
local function verifyZeros(base, byteCount)
    local step   = 4   -- DWORD step
    local slots  = {}
    local addr   = base
    while addr < base + byteCount do
        slots[#slots + 1] = { address = addr, flags = 4 }
        addr = addr + step
    end
    if #slots == 0 then return true end
    local results = gg.getValues(slots)
    if not results then return false end
    for _, v in ipairs(results) do
        if v.value ~= 0 then return false end
    end
    return true
end

-- Find a safe zero region using gg.getRangesList.
-- Tries progressively smaller region sizes until one is found.
local function findZeroRegion(desiredBytes)
    desiredBytes = desiredBytes or DEFAULT_REGION_BYTES
    local regions = gg.getRangesList()

    -- Try the desired size first, then shrink by half each round
    local sizes = { desiredBytes }
    local s = desiredBytes
    while s > MIN_REGION_BYTES do
        s = math.floor(s / 2)
        sizes[#sizes + 1] = s
    end

    for _, regionBytes in ipairs(sizes) do
        local dwords = math.floor(regionBytes / 4)
        if dwords >= 8 then  -- need at least 32 bytes
            for _, region in ipairs(regions) do
                local regionSize = region["end"] - region.start

                if (region.state == "O" or region.state == "Ca")
                   and not isDangerousRegion(region)
                   and regionSize >= regionBytes then

                    local base = region.start
                    local rem = base % 8
                    if rem ~= 0 then base = base + (8 - rem) end

                    if base + regionBytes <= region["end"]
                       and not isClaimed(base, regionBytes) then

                        if verifyZeros(base, regionBytes) then
                            _claimed[base] = { size = regionBytes }
                            log(string.format("found zero region: base=0x%X size=%d (wanted %d)",
                                base, regionBytes, desiredBytes))
                            return base, regionBytes
                        end
                    end
                end
            end
        end
    end

    return nil, 0
end

function M.owns(addr)
    return _registry[addr] ~= nil
end

function M.isFreed(addr)
    local e = _registry[addr]
    return e ~= nil and e.freed == true
end

-- Insert a block into the free list, coalescing with adjacent
-- free blocks to keep fragmentation down.
local function insertFree(addr, size)
    local mergedAddr, mergedSize = addr, size
    local keep = {}
    for _, b in ipairs(_freeList) do
        if b.addr + b.size == mergedAddr then
            mergedAddr = b.addr
            mergedSize = mergedSize + b.size
        elseif mergedAddr + mergedSize == b.addr then
            mergedSize = mergedSize + b.size
        else
            keep[#keep + 1] = b
        end
    end
    keep[#keep + 1] = { addr = mergedAddr, size = mergedSize }
    _freeList = keep
end

function M.free(addr)
    local e = _registry[addr]
    if not e or e.freed then
        return false
    end
    e.freed = true
    insertFree(addr, e.size)
    persistSnapshot()
    log(string.format("free(0x%X) reclaimed %d bytes", addr, e.size))
    return true
end

-- Test/recovery hook: forget in-memory state WITHOUT touching the
-- persisted cache. The next allocate() rebuilds via restoreFromCache
-- — the same code path a script reload takes.
function M._reset()
    zeroPageBase, zeroPageCursor, zeroPageSize = nil, 0, 0
    _claimed, _registry, _freeList = {}, {}, {}
    _restoreTried = false
end

function M.allocate(size)
    size = (size + 7) & ~7  -- align to 8 bytes

    -- Rebuild from the PID-scoped cache FIRST — the best-fit scan
    -- below must see free blocks restored by a previous run.
    if zeroPageBase == nil then
        restoreFromCache()
    end

    -- Prefer a reclaimed block (best fit). Freed blocks hold stale
    -- data, so they are re-zeroed HERE, at reuse time — not at free
    -- time — which keeps a freed block's bytes valid for any in-flight
    -- game read until Nebula actually hands the memory out again.
    local bestIdx, best
    for i, b in ipairs(_freeList) do
        if b.size >= size and (best == nil or b.size < best.size) then
            bestIdx, best = i, b
        end
    end
    if best then
        local addr = best.addr
        local zeroWrites = {}
        for off = 0, size - 1, 8 do
            zeroWrites[#zeroWrites + 1] = { address = addr + off, flags = Memory.FLAGS.INT64, value = 0 }
        end
        if Memory.writeBatch(zeroWrites) then
            if best.size > size then
                best.addr = addr + size
                best.size = best.size - size
            else
                table.remove(_freeList, bestIdx)
            end
            _registry[addr] = { size = size, freed = false }
            log(string.format("allocate(%d) -> 0x%X (reclaimed, zeroed)", size, addr))
            return addr
        end
        log("reclaimed block re-zeroing failed; bump-allocating instead")
    end

    if zeroPageBase == nil
       or zeroPageCursor + size > zeroPageSize then
        local desired = math.max(size * 4, DEFAULT_REGION_BYTES)
        zeroPageBase, zeroPageSize = findZeroRegion(desired)
        if zeroPageBase == nil then
            zeroPageBase, zeroPageSize = findZeroRegion(size)
        end
        if zeroPageBase == nil then
            log(string.format("allocate(%d) FAILED: no safe zero region found", size))
            return nil
        end
        -- Region header: the magic QWORD lets a later run verify
        -- the region still holds OUR data. Byte 0 is reserved;
        -- allocations start at +8.
        local magicOk = Memory.writeBatch({
            { address = zeroPageBase, flags = Memory.FLAGS.INT64, value = MAGIC },
        })
        if not magicOk then
            zeroPageBase = nil
            log("allocate: region header write failed")
            return nil
        end
        zeroPageCursor = 8
        persistSnapshot()
    end

    local addr = zeroPageBase + zeroPageCursor
    zeroPageCursor = zeroPageCursor + size
    _registry[addr] = { size = size, freed = false }
    log(string.format("allocate(%d) -> 0x%X (region=0x%X cursor=%d/%d)",
        size, addr, zeroPageBase, zeroPageCursor, zeroPageSize))
    return addr
end

function M._status()
    return {
        base   = zeroPageBase,
        cursor = zeroPageCursor,
        size   = zeroPageSize,
        magic  = MAGIC,
        freeBlocks = #_freeList,
        claimed = (function()
            local n = 0
            for _ in pairs(_claimed) do n = n + 1 end
            return n
        end)()
    }
end

return M
]]

__vfs['core/defineApi.lua'] = [[--==================================================
-- core/defineApi.lua
--==================================================
-- Generic bridge between an API definition:
--
--   Nebula.defineApi({
--       struct  = "EventDefinition",
--       resolve = function() ... return address, err end,
--   })
--
-- and Nebula's existing struct/field/memory machinery. This is NOT
-- a second parallel API architecture — every get()/set() below
-- routes through the same core/Type.lua, core/Repeated.lua and
-- core/Struct.lua modules the hand-written api/*.lua files always
-- used. What used to be copy-pasted into every event module
-- (resolvePath, readFieldById, writeFieldById, walkFields, the
-- String/Array ABI shadowing) now lives here once.
--
-- Metadata is never version-pinned by the caller: defineApi()
-- resolves the struct's metadata automatically through
-- metadata/manifest.lua, keyed on the struct name and the running
-- game's two-component version. See that file for the resolution
-- rules.
--
-- No field filtering: every field present in the resolved struct
-- metadata is reachable through get()/set()/fields()/meta() —
-- there is no whitelist/blacklist concept here, by design (see
-- metadata/1.73/structs/EventDefinition.lua's header comment).

local Memory   = loadModule("core/Memory.lua")
local Struct   = loadModule("core/Struct.lua")
local Type     = loadModule("core/Type.lua")
local Repeated = loadModule("core/Repeated.lua")
local Path     = loadModule("core/Path.lua")
local Manifest = loadModule("metadata/manifest.lua")
local Trace = loadModule("core/Trace.lua")

local M = {}

-- Per-API log label (config.name, e.g. "PublicEvent") so trace lines
-- read "[PublicEvent] ..." / "[TeamEvent] ..." / "[CommunityEvent] ..."
-- — defaults to the struct name when no label is configured.
local Logfile = loadModule("core/Logfile.lua")

local function log(label, ...)
    if Nebula ~= nil and Nebula.log then
        Logfile.log("[" .. label .. "]", ...)
    end
end

-- Same cooldown convention as every hand-written api/*.lua module:
-- when no struct instance is currently resolvable, don't re-run an
-- expensive scan on every single get()/set() call.
local FAIL_RETRY_SECONDS = 5

local function nowSec()
    if os.clock then return os.clock() end
    return os.time()
end

---A field is a leaf (readable) entry iff its own `type` is a
---string. Pure namespace containers (sessionEntry, gameMode) have
---no `type` of their own — only typed children.
local function isLeafField(node)
    return type(node) == "table" and type(node.type) == "string"
end

local function isOffsetKnown(field)
    return field.offset ~= nil and field.offset ~= 0xBAAD
end

---Resolve the child-field template of a `type = "Object"` field —
---the pattern that makes PlayerInfo.gameStatus.vipStatus work:
---the Object field's own table carries
---the nested struct's fields injected next to `offset`/`type`.
---Also accepted (1.73 EventDefinition.specialFeatures shape): an
---`elements` template table on the Object field. Both are the same
---read: QWORD at base+offset -> nested object base -> fields there.
---Returns nil for genuinely childless Object fields (still rejected).
---The returned template preserves the parent field's `stringDirect`
---property so the subtree uses the correct string ABI. We shallow-copy
---the elements table so `pairs()` iteration (used by Struct.get) sees
---all fields; `stringDirect` is stored directly on the copy.
local function objectChildTemplate(field)
    if type(field) ~= "table" then return nil end
    for _, v in pairs(field) do
        if type(v) == "table" and type(v.offset) == "number" then
            return field        -- vipStatus pattern: injected children
        end
    end
    if type(field.elements) == "table" then
        local tpl = {}
        for k, v in pairs(field.elements) do
            tpl[k] = v
        end
        -- Preserve stringDirect on the template for ABI propagation
        if field.stringDirect ~= nil then
            tpl.stringDirect = field.stringDirect
        end
        return tpl
    end
    return nil
end

---Shadow a String field with indirect=false when the ABI inlines
---strings (every EventDefinition-backed API does). Does NOT
---mutate the shared metadata — returns a shadow table.
local function shadowStringDirect(field, direct)
    if direct and field.type == "String" and field.indirect == nil then
        return setmetatable({ indirect = false }, { __index = field })
    end
    return field
end

---Shadow an Array-with-elements field to add stringDirect +
---container ABI hints without mutating the shared metadata.
local function shadowStringDirectArray(field, direct, container)
    if field.stringDirect == nil and direct then
        return setmetatable({ stringDirect = true, container = container or "vector" }, { __index = field })
    end
    return field
end

---Build the API module for one defineApi() config. Kept as a
---factory (not exposed directly) so multiple calls with different
---configs never share state.
---@param config table @ { struct = string, resolve = function, stringDirect = boolean|nil, container = string|nil }
---A type = "Object" field in the struct metadata may declare its own
---`stringDirect` key: the subtree behind that pointer then uses THAT
---ABI (e.g. PlayerInfo.gameStatus is `stringDirect = false` — the
---proto2 GameStatus family with indirect strings and protobuf array
---headers — instead of PlayerInfo's inline/vector ABI).
function M.create(config)
    assert(type(config) == "table", "defineApi requires a config table")
    assert(type(config.struct) == "string" and config.struct ~= "", "defineApi requires config.struct")
    assert(type(config.resolve) == "function", "defineApi requires config.resolve")

    -- Every event struct currently migrated to this system inlines
    -- its strings and uses std::vector arrays — same default every
    -- hand-written event api module hardcoded. A future struct with
    -- a different ABI can override either via config.
    local opts = {
        stringDirect = config.stringDirect ~= false,
        container    = config.container or "vector",
    }

    local label = config.name or config.struct
    local function apilog(...)
        log(label, ...)
    end

    ---Standardized address-trace record — see core/Trace.lua. Every
    ---defineApi-backed module (current and future) emits the same
    ---record format automatically from here.
    local function rec(tag, kv)
        Trace.rec(label, tag, kv)
    end

    local mod = {}
    mod.struct = config.struct
    mod.name = label
    -- Exposed for tests only (see test/defineApi_spec.lua) — lets a
    -- test confirm the real resolver function was wired in, without
    -- needing to execute it against a live device.
    mod._resolve = config.resolve

    --==================================================
    -- Metadata resolution (automatic, per metadata/manifest.lua)
    --==================================================

    local resolvedMetadata, resolvedVersion = nil, nil

    local function resolveMetadata()
        if resolvedMetadata ~= nil then
            return resolvedMetadata
        end
        local metadata, version, err = Manifest.resolve(config.struct)
        if not metadata then
            rec("null", { STRUCT = config.struct, ERR = "metadata_resolution_failed: " .. tostring(err) })
            error("defineApi(" .. config.struct .. "): metadata resolution failed: " .. tostring(err))
        end
        rec("meta", { STRUCT = config.struct, VER = version,
            INFO = "top_level_keys=" .. (function()
                local n = 0
                for _ in pairs(metadata) do n = n + 1 end
                return n
            end)() })
        resolvedMetadata, resolvedVersion = metadata, version
        return resolvedMetadata
    end

    -- Lazily resolved so constructing the module never fails just
    -- because the game/device isn't attached yet.
    mod.metadata = setmetatable({}, {
        __index = function(_, k) return resolveMetadata()[k] end,
    })

    ---@return string|nil version @ the metadata version currently in use (e.g. "1.73")
    function mod.metadataVersion()
        resolveMetadata()
        return resolvedVersion
    end

    --==================================================
    -- Base address resolution
    --==================================================

    local baseAddress = nil
    local lastFailErr, lastFailClock = nil, nil

    local function resolveBase(forceRescan)
        if baseAddress ~= nil and not forceRescan then
            rec("resolve", { MODE = "warm", ADDR = baseAddress, STRUCT = config.struct })
            return baseAddress
        end

        if lastFailErr ~= nil and not forceRescan
            and (nowSec() - lastFailClock) < FAIL_RETRY_SECONDS then
            apilog(string.format("resolveBase: still in fail-cooldown (%.1fs left): %s",
                FAIL_RETRY_SECONDS - (nowSec() - lastFailClock), tostring(lastFailErr)))
            return nil, lastFailErr
        end

        local address, err = config.resolve()
        if not address then
            lastFailErr = err or "base_not_found"
            lastFailClock = nowSec()
            rec("null", { ADDR = "NULL/INVALID", ERR = "resolveBase_failed: " .. tostring(lastFailErr) })
            return nil, lastFailErr
        end

        baseAddress = address
        lastFailErr, lastFailClock = nil, nil
        rec("resolve", { MODE = "cold", ADDR = address, STRUCT = config.struct,
            VER = resolvedVersion, INFO = forceRescan and "forced_rescan" or nil })
        return baseAddress
    end
    mod.resolveBase = resolveBase

    --==================================================
    -- Field lookup (dotted id, with optional array indices)
    --==================================================

    local function resolvePath(id)
        local segments = Path.parse(id)
        if #segments == 0 then
            apilog("resolvePath: empty path")
            return nil, "empty_path"
        end

        local base, baseErr = resolveBase()
        if not base then
            apilog("resolvePath '" .. tostring(id) .. "': base resolution failed: " .. tostring(baseErr))
            return nil, baseErr
        end

        local metadata = resolveMetadata()
        local currentBase = base
        local currentMeta = metadata
        local finalField = nil

        -- ABI state threading. opts.stringDirect describes THIS
        -- struct's string/array ABI (inline vs pointer-deref'd
        -- strings, vector vs protobuf arrays). Struct families with
        -- a DIFFERENT ABI are entered through a type = "Object"
        -- field that declares its own `stringDirect` key (e.g.
        -- PlayerInfo.gameStatus -> the proto2 GameStatus subtree
        -- is `stringDirect = false`: indirect strings + protobuf
        -- array headers, exactly as raw metadata declares them).
        -- The state is inherited downward and used for the final
        -- field's dispatch — a leaf never re-applies the root ABI
        -- to a subtree that declared its own.
        local currentDirect = opts.stringDirect

        rec("path", { PATH = tostring(id), ADDR = base, SEG = #segments })

        for i, seg in ipairs(segments) do
            local node = currentMeta[seg.name]
            if node == nil then
                apilog(string.format("resolvePath: seg[%d] '%s' NOT FOUND in metadata", i, seg.name))
                return nil, "unknown_field: " .. tostring(id)
            end

            if seg.index ~= nil then
                if node.type ~= "Array" then
                    apilog(string.format("resolvePath: seg[%d] '%s[%d]' indexed but type=%s is not Array", i, seg.name, seg.index, tostring(node.type)))
                    return nil, "not_an_array: " .. seg.name
                end
                if not isOffsetKnown(node) then
                    apilog(string.format("resolvePath: seg[%d] '%s[%d]': offset_unknown", i, seg.name, seg.index))
                    return nil, "offset_unknown: " .. seg.name
                end
                local arr, arrErr = Repeated.get(currentBase, shadowStringDirectArray(node, currentDirect, opts.container))
                if not arr then
                    apilog(string.format("resolvePath: '%s[%d]' array read FAILED: %s", seg.name, seg.index, tostring(arrErr)))
                    return nil, arrErr
                end
                local luaIdx = seg.index
                if luaIdx < 1 or luaIdx > #arr then
                    apilog(string.format("resolvePath: '%s[%d]' REJECTED: index out of bounds (size=%d)", seg.name, seg.index, #arr))
                    return nil, string.format("index_out_of_bounds: %s[%d] (size=%d)", seg.name, seg.index, #arr)
                end
                if i == #segments then
                    local elemStride = node.elementStride or 0x8
                    local header, _ = Repeated.readHeaderForSet(currentBase, shadowStringDirectArray(node, currentDirect, opts.container))
                    local writeAddr = nil
                    local writeErr = nil
                    if header and header.arrayPtr and header.arrayPtr ~= 0 then
                        if elemStride > 0x8 then
                            writeAddr = header.arrayPtr + (seg.index - 1) * elemStride
                        else
                            local slots, _ = Memory.readBatchChunked({
                                { address = header.arrayPtr + (seg.index - 1) * 0x8, flags = Memory.FLAGS.INT64 }
                            })
                            if slots and slots[1] and slots[1].value ~= 0 then
                                writeAddr = slots[1].value
                            else
                                writeErr = "null_element_ptr"
                            end
                        end
                    else
                        writeErr = "null_array_ptr"
                    end
                    return { value = arr[luaIdx], resolved = true, writeAddr = writeAddr, writeErr = writeErr, elementType = node.elementType, elements = node.elements, direct = currentDirect }
                end
                if node.elements then
                    local stride = node.elementStride or 0x8
                    if stride > 0x8 then
                        local header, hErr = Repeated.readHeaderForSet(currentBase, shadowStringDirectArray(node, currentDirect, opts.container))
                        if not header then return nil, hErr end
                        currentBase = header.arrayPtr + (seg.index - 1) * stride
                        rec("elem", { PATH = tostring(id), FIELD = seg.name,
                            IDX = seg.index - 1, PTR = header.arrayPtr,
                            ELEM = currentBase, NESTED = currentBase, STRIDE = stride })
                    else
                        local h, he = Repeated.readHeaderForSet(currentBase, shadowStringDirectArray(node, currentDirect, opts.container))
                        if not h then return nil, he end
                        local slotAddr = h.arrayPtr + (seg.index - 1) * 0x8
                        local slots, sErr = Memory.readBatchChunked({
                            { address = slotAddr, flags = Memory.FLAGS.INT64 }
                        })
                        if not slots or not slots[1] or slots[1].value == 0 then
                            rec("null", { PATH = tostring(id), FIELD = seg.name,
                                IDX = seg.index - 1, SLOT = slotAddr,
                                ADDR = "NULL/INVALID", ERR = "null_element_ptr" })
                            return nil, "null_element_ptr"
                        end
                        currentBase = slots[1].value
                        rec("elem", { PATH = tostring(id), FIELD = seg.name,
                            IDX = seg.index - 1, SLOT = slotAddr, PTR = h.arrayPtr,
                            ELEM = currentBase, NESTED = currentBase })
                    end
                    currentMeta = node.elements
                else
                    return nil, "array_has_no_elements: " .. seg.name
                end
            elseif isLeafField(node) and i == #segments then
                rec("path", { PATH = tostring(id), FIELD = seg.name, SEG = i,
                    TYPE = tostring(node.type), OFF = node.offset or 0,
                    ADDR = currentBase + (node.offset or 0) })
                finalField = node
                break
            elseif type(node) == "table" and node.type == "Object" and i < #segments then
                -- mid-path Object: descend via the field QWORD —
                -- same chain as GameStatus (e.g. "vipStatus.isVip").
                if not isOffsetKnown(node) then
                    return nil, "offset_unknown: " .. seg.name
                end
                local template = objectChildTemplate(node)
                if not template then
                    return nil, "object_has_no_children: " .. seg.name
                end
                rec("path", { PATH = tostring(id), FIELD = seg.name, SEG = i,
                    TYPE = "Object", OFF = node.offset or 0,
                    ADDR = currentBase + (node.offset or 0) })
                local ptr = Memory.deref(currentBase, node.offset)
                if not ptr or ptr == 0 then
                    rec("null", { PATH = tostring(id), FIELD = seg.name,
                        OFF = node.offset or 0, PTR = "NULL/INVALID",
                        ERR = "null_pointer" })
                    return nil, "null_pointer: " .. seg.name
                end
                rec("nested", { PATH = tostring(id), FIELD = seg.name,
                    OFF = node.offset or 0, QWORD = ptr, PTR = ptr,
                    NESTED = ptr, INFO = "mid_path_object" })
                currentBase = ptr
                currentMeta = template
                if node.stringDirect ~= nil then
                    currentDirect = node.stringDirect
                    rec("meta", { PATH = tostring(id), FIELD = seg.name,
                        INFO = "abi_override stringDirect="
                            .. tostring(currentDirect) })
                end
            elseif type(node) == "table" and not isLeafField(node) and i < #segments then
                apilog(string.format("resolvePath: seg[%d] '%s' namespace container (descending)", i, seg.name))
                currentMeta = node
            else
                apilog(string.format("resolvePath: seg[%d] '%s' unresolvable node shape", i, seg.name))
                return nil, "unknown_field: " .. tostring(id)
            end
        end

        if finalField then
            return { field = finalField, base = currentBase, direct = currentDirect }
        end
        return nil, "unknown_field: " .. tostring(id)
    end
    -- Exposed for focused tests (see test/defineApi_spec.lua) — not
    -- part of the documented public surface.
    mod._resolvePath = resolvePath

    local function readFieldById(id)
        local result, err = resolvePath(id)
        if not result then
            return nil, err
        end

        if result.resolved then
            return result.value
        end

        local field = result.field
        local base = result.base

        if field.type == "Object" then
            -- vipStatus pattern (see objectChildTemplate): an
            -- Object field is read by taking the QWORD at
            -- base+offset — the nested object's runtime base (e.g. a
            -- std::list's START QWORD) — and reading the nested
            -- fields AT that base. No extra offsets. NULL/0 is
            -- recorded and rejected, never blindly dereferenced.
            local template = objectChildTemplate(field)
            if template and isOffsetKnown(field) then
                local fieldAddr = base + field.offset
                rec("get", { PATH = tostring(id), TYPE = "Object",
                    OFF = field.offset, ADDR = fieldAddr,
                    INFO = "qword-read" })
                local ptr = Memory.deref(base, field.offset)
                if not ptr or ptr == 0 then
                    rec("null", { PATH = tostring(id), TYPE = "Object",
                        OFF = field.offset, ADDR = fieldAddr,
                        PTR = "NULL/INVALID", ERR = "null_pointer" })
                    return nil, "null_pointer: " .. tostring(id)
                end
                rec("nested", { PATH = tostring(id), FIELD = tostring(id),
                    OFF = field.offset, ADDR = fieldAddr, QWORD = ptr,
                    PTR = ptr, NESTED = ptr, INFO = "object_base" })
                -- field.stringDirect may be FALSE (a proto2 subtree
                -- boundary like gameStatus). A plain `a and b or c`
                -- chain falls through to result.direct when the
                -- override is false — leaking the root ABI past
                -- the boundary — so pick it explicitly.
                local leafDirect = result.direct
                if field.stringDirect ~= nil then
                    leafDirect = field.stringDirect
                end
                return Struct.get(ptr, template, leafDirect, tostring(id))
            end
            apilog("get '" .. tostring(id) .. "': Object type — not readable, rejected (no nested metadata)")
            return nil, "unsupported_type: Object fields are not yet readable (missing nested metadata)"
        end

        if not isOffsetKnown(field) then
            apilog(string.format("get '%s': offset_unknown (0x%X placeholder)", tostring(id), field.offset or 0))
            return nil, "offset_unknown: " .. id
        end

        if field.type == "Array" then
            rec("get", { PATH = tostring(id), TYPE = "Array",
                OFF = field.offset or 0, ADDR = base + (field.offset or 0),
                ELEM_TYPE = field.elementType, STRIDE = field.elementStride or 0x8 })
            return Repeated.get(base, shadowStringDirectArray(field, result.direct, opts.container), nil, tostring(id))
        end

        if field.repeated then
            apilog(string.format("get '%s': dispatching repeated read (base=0x%X + offset=0x%X)",
                tostring(id), base, field.offset or 0))
            return Repeated.get(base, field)
        end

        local impl = Type.resolve(field.type)
        if not impl then
            apilog("get '" .. tostring(id) .. "': no_type_impl '" .. tostring(field.type) .. "'")
            return nil, "no_type_impl: " .. tostring(field.type)
        end

        rec("get", { PATH = tostring(id), TYPE = tostring(field.type),
            OFF = field.offset or 0, ADDR = base + (field.offset or 0) })
        return impl.get(base, shadowStringDirect(field, result.direct))
    end

    local function writeFieldById(id, value)
        local result, err = resolvePath(id)
        if not result then
            return false, err
        end

        if result.resolved then
            if not result.writeAddr then
                local werr = result.writeErr or "cannot_set_array_element_value_directly"
                apilog(string.format("set '%s': element not writable (%s) — rejected", tostring(id), tostring(werr)))
                return false, werr
            end
            -- Whole element-struct write (elements-template array):
            -- Struct.set AT the element address with the template,
            -- mirroring the whole-Object write semantics — partial
            -- values are allowed, only the provided keys are
            -- written, and the existing instance is edited in
            -- place, never re-allocated.
            if result.elements then
                if type(value) ~= "table" then
                    apilog("set '" .. tostring(id) .. "': element struct write REJECTED — value is not a table")
                    return false, "value_not_table"
                end
                rec("set", { PATH = tostring(id), TYPE = "Element",
                    OFF = 0, ADDR = result.writeAddr,
                    INFO = "element_template" })
                local ok = Struct.set(result.writeAddr, result.elements, value, result.direct)
                if not ok then
                    apilog("set '" .. tostring(id) .. "': element struct write FAILED")
                    return false, "write_failed"
                end
                return true, nil
            end
            local elemType = result.elementType
            if not elemType then
                return false, "unknown_element_type"
            end
            local impl = Type.resolve(elemType)
            if not impl then
                return false, "no_type_impl: " .. tostring(elemType)
            end
            local f = { offset = 0, type = elemType }
            if elemType == "String" then
                -- vector/stringDirect arrays inline their string
                -- elements; proto2 subtrees (direct=false) keep the
                -- String impl's indirect default
                f = shadowStringDirect(f, result.direct)
            end
            local ok = impl.set(result.writeAddr, f, value)
            if not ok then
                return false, "write_failed"
            end
            return true, nil
        end

        local field = result.field
        local base = result.base

        if field.type == "Object" then
            -- Write twin of readFieldById's Object branch: QWORD at
            -- base+offset is the nested object's runtime base;
            -- Struct.set writes the provided fields AT that base.
            -- NULL/0 is recorded and rejected, never blindly
            -- dereferenced. Never allocates a new object — a whole
            -- Object set only edits the existing instance.
            local template = objectChildTemplate(field)
            if template and isOffsetKnown(field) then
                local fieldAddr = base + field.offset
                rec("set", { PATH = tostring(id), TYPE = "Object",
                    OFF = field.offset, ADDR = fieldAddr,
                    INFO = "qword-write" })
                local ptr = Memory.deref(base, field.offset)
                if not ptr or ptr == 0 then
                    rec("null", { PATH = tostring(id), TYPE = "Object",
                        OFF = field.offset, ADDR = fieldAddr,
                        PTR = "NULL/INVALID", ERR = "null_pointer" })
                    return false, "null_pointer: " .. tostring(id)
                end
                rec("nested", { PATH = tostring(id), FIELD = tostring(id),
                    OFF = field.offset, ADDR = fieldAddr, QWORD = ptr,
                    PTR = ptr, NESTED = ptr, INFO = "object_base" })
                -- field.stringDirect may be FALSE (a proto2 subtree boundary).
                -- Explicit pick: `a and b or c` falls through to
                -- result.direct on a false override.
                local leafDirect = result.direct
                if field.stringDirect ~= nil then
                    leafDirect = field.stringDirect
                end
                local ok = Struct.set(ptr, template, value, leafDirect)
                if not ok then
                    apilog("set '" .. tostring(id) .. "': Object write FAILED")
                    return false, "write_failed"
                end
                return true, nil
            end
            return false, "unsupported_type: Object fields are not yet writable (missing nested metadata)"
        end

        if not isOffsetKnown(field) then
            return false, "offset_unknown: " .. id
        end

        if field.type == "Array" then
            return Repeated.set(base, shadowStringDirectArray(field, result.direct, opts.container), value)
        end

        if field.repeated then
            return Repeated.set(base, field, value)
        end

        local impl = Type.resolve(field.type)
        if not impl then
            apilog("set '" .. tostring(id) .. "': no_type_impl '" .. tostring(field.type) .. "'")
            return false, "no_type_impl: " .. tostring(field.type)
        end

        rec("set", { PATH = tostring(id), TYPE = tostring(field.type),
            OFF = field.offset or 0, ADDR = base + (field.offset or 0) })
        local ok = impl.set(base, shadowStringDirect(field, result.direct), value)
        if not ok then
            apilog("set '" .. tostring(id) .. "': write FAILED")
            return false, "write_failed"
        end
        return true, nil
    end

    --==================================================
    -- get()
    --==================================================

    ---@param id string|nil @ omit to get an accessor bound to the currently-resolved struct instance
    ---@return any|nil value, string|nil error
    function mod.get(id)
        local base, baseErr = resolveBase()
        if not base then
            apilog("get: base unresolved (" .. tostring(baseErr) .. ")")
            return nil, baseErr
        end

        if id == nil then
            apilog(string.format("get(): accessor bound to base=0x%X", base))
            return {
                base = base,
                get = function(fieldId) return readFieldById(fieldId) end,
            }
        end

        local op = Trace.beginOp(label, "get", { ADDR = base, STRUCT = config.struct })
        local value, err = readFieldById(id)
        Trace.fieldDone(op, tostring(id), value ~= nil or err == nil)
        Trace.endOp(op)
        return value, err
    end

    --==================================================
    -- set() — chainable operation object supporting :dry()
    --==================================================

    local SetOperation = {}
    SetOperation.__index = SetOperation

    local function performWrite(op)
        if op._dry then
            local result, dryErr = resolvePath(op.id)
            if not result then
                apilog("set(dry) '" .. tostring(op.id) .. "': path resolution failed — " .. tostring(dryErr))
                return false, dryErr
            end
            if result.resolved then
                apilog(string.format("set(dry) '%s': element path resolvable (writable=%s, template=%s) — no write performed",
                    tostring(op.id), tostring(result.writeAddr ~= nil),
                    tostring(result.elements ~= nil or result.elementType ~= nil)))
            else
                apilog("set(dry) '" .. tostring(op.id) .. "': path resolvable, no write performed")
            end
            return true, nil
        end
        return writeFieldById(op.id, op.value)
    end

    function SetOperation:dry()
        self._dry = true
        return performWrite(self)
    end

    --==================================================
    -- :verify() — read-back verification. Compares the value
    -- actually in memory against the one this operation wrote
    -- (or intended to write). Numbers compare with a small
    -- float32 tolerance; tables compare recursively over the
    -- EXPECTED keys only, so a partial element-struct write
    -- verifies against a full read-back cleanly.
    --==================================================

    local function valuesMatch(expected, actual)
        if type(expected) == "number" and type(actual) == "number" then
            return math.abs(expected - actual) <= 1e-4
        end
        if type(expected) ~= type(actual) then
            return false
        end
        if type(expected) == "table" then
            for k, v in pairs(expected) do
                if not valuesMatch(v, actual[k]) then
                    return false
                end
            end
            return true
        end
        return expected == actual
    end

    function SetOperation:verify()
        if self._dry then
            return self
        end
        if not self._ok then
            self._verified = false
            self._actual = nil
            return self
        end
        local actual = readFieldById(self.id)
        self._actual = actual
        self._verified = valuesMatch(self.value, actual)
        if not self._verified then
            apilog(string.format("verify '%s': READ-BACK MISMATCH — expected=%s actual=%s",
                tostring(self.id), tostring(self.value), tostring(actual)))
        end
        return self
    end

    setmetatable(SetOperation, {
        __call = function(cls, id, value)
            local self = setmetatable({ id = id, value = value, _dry = false }, cls)
            local op = Trace.beginOp(label, "set", { STRUCT = config.struct })
            Trace.fieldDone(op, tostring(id), true) -- marked below by outcome
            local ok, err = performWrite(self)
            op.slow[#op.slow].ok = ok
            if not ok then
                op.ok, op.fail = op.ok - 1, op.fail + 1
                rec("null", { PATH = tostring(id), ERR = "set_failed: " .. tostring(err) })
            end
            Trace.endOp(op)
            self._ok, self._err = ok, err
            return self
        end
    })

    ---@param id string @ dotted field id
    ---@param value any
    ---@return table operation @ chainable; already executed
    function mod.set(id, value)
        return SetOperation(id, value)
    end

    --==================================================
    -- fields() / meta() — read-only introspection
    --==================================================

    local function walkFields(node, prefix, results)
        for key, child in pairs(node) do
            if type(child) == "table" then
                local id = prefix and (prefix .. "." .. key) or key
                if isLeafField(child) then
                    if isOffsetKnown(child) then
                        results[#results + 1] = id
                    end
                else
                    walkFields(child, id, results)
                end
            end
        end
    end

    ---List every offset-verified field's dotted id — every field
    ---the resolved struct metadata defines, with no filtering.
    ---@return string[] ids
    function mod.fields()
        local results = {}
        walkFields(resolveMetadata(), nil, results)
        table.sort(results)
        return results
    end

    ---@param id string
    ---@return table|nil metaView, string|nil error
    function mod.meta(id)
        local result, err = resolvePath(id)
        local field = result and result.field
        if not field then
            return nil, err
        end

        local view = {
            name     = id,
            type     = field.type,
            offset   = field.offset,
            repeated = field.repeated == true or field.type == "Array",
            known    = isOffsetKnown(field),
        }

        if baseAddress ~= nil and view.known then
            view.address = baseAddress + field.offset
        end

        return view
    end

    return mod
end

return M
]]

