    local name = enum.byId and enum.byId[raw]
    if name ~= nil then
        return name
    end
    if raw ~= 0 then
        log(string.format("[get] at 0x%X offset=0x%X: raw=%d not in enum '%s', returning raw",
            baseAddress, field.offset, raw, tostring(field.enum)))
    end
