            and grown2[3].maxCollectAmount == 777,
        tostring(grown2[1] and grown2[1].maxCollectAmount) .. "/" ..
        tostring(grown2[2] and grown2[2].maxCollectAmount) .. "/" ..
        tostring(grown2[3] and grown2[3].maxCollectAmount))
    check("grown tiers landed",
